def fib(n):
    if n <= 1: return n
    return fib(n-1) + fib(n-2)

def is_palindrome(s):
    s = s.lower().replace(' ', '')
    return s == s[::-1]

def two_sum(nums, target):
    l, r = 0, len(nums) - 1
    while l < r:
        s = nums[l] + nums[r]
        if s == target: return (l, r)
        if s < target: l += 1
        else: r -= 1

def two_sum_hash(nums, target):
    seen = {}
    for i, n in enumerate(nums):
        diff = target - n
        if diff in seen: return (seen[diff], i)
        seen[n] = i

def bfs(graph, start):
    q, visited = deque([start]), {start}
    while q:
        curr = q.popleft()
        for nbor in graph[curr]:
            if nbor not in visited:
                visited.add(nbor); q.append(nbor)

def dfs(graph, curr, visited=None):
    if visited is None: visited = set()
    visited.add(curr)
    for nbor in graph[curr]:
        if nbor not in visited:
            dfs(graph, nbor, visited)

class Singleton:
    _instance = None
    def __new__(cls):
        if not cls._instance:
            cls._instance = super().__new__(cls)
        return cls._instance

def read_chunks(path, size=1024):
    with open(path, 'rb') as f:
        while chunk := f.read(size):
            yield chunk

def merge(l, r):
    res, i, j = [], 0, 0
    while i < len(l) and j < len(r):
        if l[i] < r[j]: res.append(l[i]); i += 1
        else: res.append(r[j]); j += 1
    return res + l[i:] + r[j:]

def char_freq(s):
    freq = {}
    for char in s:
        freq[char] = freq.get(char, 0) + 1
    return freq

